package com.geekmall.search;
import com.fasterxml.jackson.databind.*;import com.geekmall.common.domain.DistributedId;import com.geekmall.common.security.AuthPrincipal;import org.springframework.amqp.AmqpRejectAndDontRequeueException;import org.springframework.amqp.rabbit.annotation.RabbitListener;import org.springframework.amqp.rabbit.core.RabbitTemplate;import org.springframework.beans.factory.annotation.Value;import org.springframework.dao.DuplicateKeyException;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.net.URI;import java.net.http.*;import java.util.*;
@Service class SearchService{private final ElasticsearchGateway es;private final JdbcTemplate jdbc;private final ObjectMapper mapper;private final RabbitTemplate rabbit;private final String productUrl,internalKey;private final HttpClient http=HttpClient.newHttpClient();SearchService(ElasticsearchGateway e,JdbcTemplate j,ObjectMapper m,RabbitTemplate r,@Value("${geek.product-service-url}")String p,@Value("${geek.internal-key}")String k){es=e;jdbc=j;mapper=m;rabbit=r;productUrl=p;internalKey=k;}
 Map<String,Object>search(String keyword,Long categoryId,List<Long>brandIds,Long shopId,Double priceMin,Double priceMax,String sort,int page,int pageSize,AuthPrincipal principal){Map<String,Object>p=new LinkedHashMap<>();p.put("keyword",keyword==null?"":keyword);p.put("categoryId",categoryId);p.put("brandIds",brandIds==null?List.of():brandIds);p.put("shopId",shopId);p.put("priceMin",priceMin);p.put("priceMax",priceMax);p.put("sort",sort);p.put("page",Math.max(1,page));p.put("pageSize",Math.min(100,Math.max(1,pageSize)));JsonNode root=es.search(p);List<JsonNode>items=new ArrayList<>();for(JsonNode hit:root.path("hits").path("hits"))items.add(hit.path("_source"));long total=root.path("hits").path("total").path("value").asLong();if(principal!=null&&keyword!=null&&!keyword.isBlank())jdbc.update("INSERT INTO search_history(id,user_id,keyword,searched_at) VALUES(?,?,?,CURRENT_TIMESTAMP)",DistributedId.next(),principal.userId(),keyword);return Map.of("items",items,"page",p.get("page"),"pageSize",p.get("pageSize"),"total",total,"hasNext",((int)p.get("page"))*((int)p.get("pageSize"))<total,"facets",root.path("aggregations"));}
 List<String>suggest(String keyword){return es.suggest(keyword);}List<Map<String,Object>>hot(){return jdbc.queryForList("SELECT keyword,score FROM search_hot_word WHERE status='ENABLED' AND (start_at IS NULL OR start_at<=CURRENT_TIMESTAMP) AND (end_at IS NULL OR end_at>=CURRENT_TIMESTAMP) ORDER BY score DESC LIMIT 20");}
 @RabbitListener(queues=SearchRabbitConfiguration.Q) @Transactional void consume(String body){try{JsonNode e=mapper.readTree(body);String eventId=e.path("eventId").asText();try{jdbc.update("INSERT INTO event_consume_log(consumer_group,event_id,processed_at,result) VALUES('search-product-index',?,CURRENT_TIMESTAMP,'PROCESSING')",eventId);}catch(DuplicateKeyException duplicate){return;}String type=e.path("eventType").asText(),id=e.path("aggregateId").asText();if(type.endsWith("on-sale.v1"))es.index(id,e.path("payload"));else if(type.endsWith("off-sale.v1"))es.delete(id);jdbc.update("UPDATE event_consume_log SET result='SUCCESS',processed_at=CURRENT_TIMESTAMP WHERE consumer_group='search-product-index' AND event_id=?",eventId);}catch(Exception ex){throw new AmqpRejectAndDontRequeueException("商品索引事件处理失败",ex);}}
 int replayDeadLetters(){int n=0;for(int i=0;i<100;i++){var msg=rabbit.receive(SearchRabbitConfiguration.DLQ);if(msg==null)break;try{String body=new String(msg.getBody(),java.nio.charset.StandardCharsets.UTF_8);String type=mapper.readTree(body).path("eventType").asText();rabbit.convertAndSend(SearchRabbitConfiguration.EX,type,body);n++;}catch(Exception e){throw new com.geekmall.common.api.BusinessException("SR50003","死信消息格式无效");}}return n;}
 @Scheduled(initialDelayString="${geek.search.bootstrap-delay:8000}",fixedDelayString="${geek.search.reconcile-interval:300000}") void scheduledReconcile(){try{reindex();}catch(Exception ignored){}}
 synchronized Map<String,Object>reindex(){long log=DistributedId.next();jdbc.update("INSERT INTO search_reconcile_log(id,started_at,status) VALUES(?,CURRENT_TIMESTAMP,'RUNNING')",log);try{es.ensureIndex();var request=HttpRequest.newBuilder(URI.create(productUrl+"/api/v1/products/internal/search-documents")).header("X-Internal-Key",internalKey).GET().build();var response=http.send(request,HttpResponse.BodyHandlers.ofString());if(response.statusCode()!=200)throw new IllegalStateException("product service HTTP "+response.statusCode());JsonNode envelope=mapper.readTree(response.body()),data=envelope.path("data");int indexed=0;for(JsonNode d:data){es.index(d.path("id").asText(),d);indexed++;}jdbc.update("UPDATE search_reconcile_log SET finished_at=CURRENT_TIMESTAMP,source_count=?,indexed_count=?,status='SUCCESS' WHERE id=?",data.size(),indexed,log);return Map.of("sourceCount",data.size(),"indexedCount",indexed,"indexCount",es.count());}catch(Exception e){jdbc.update("UPDATE search_reconcile_log SET finished_at=CURRENT_TIMESTAMP,status='FAILED',error_message=? WHERE id=?",String.valueOf(e.getMessage()).substring(0,Math.min(490,String.valueOf(e.getMessage()).length())),log);throw new com.geekmall.common.api.BusinessException("SR50302","索引补偿失败："+e.getMessage());}}
 List<Map<String,Object>>reconcileLogs(){return jdbc.queryForList("SELECT id,started_at AS startedAt,finished_at AS finishedAt,source_count AS sourceCount,indexed_count AS indexedCount,status,error_message AS errorMessage FROM search_reconcile_log ORDER BY started_at DESC LIMIT 50");}
}
